#!/usr/bin/env python3
"""Regenerate bench/results/6000d-dispatch/README.md from the committed JSON."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DEST = ROOT / 'bench/results/6000d-dispatch'


def main():
    lines = ['# RTX 6000D Q4_K dispatch measurement', '',
             'Generated by `python3 bench/report_gpu_dispatch.py`.', '',
             'Two RTX 6000D GPUs, 156 SMs each, 85,651 MiB, driver 595.104.02; '
             'Mojo 1.1.0 (8189361e), max-core 26.6.0, compiled for sm_120. '
             'Each model ran on its own GPU, and each A/B pair used the same GPU. '
             'Other GPUs on the shared host had existing workloads. No power or clock settings were changed.', '',
             'Both models use mradermacher Q4_K_M GGUF files. The raw files record their '
             'names, byte sizes, GPU identities, source commits and every run. '
             'The source URLs were the corresponding Hugging Face repository resolve/main endpoints, '
             'accessed through hf-mirror.com on 2026-10-30.', '',
             'Three prompts, three measured rounds per length; a warmup pair per length is excluded. '
             'All runs use 32 forward passes, block length 32, no early stop, threshold or dual cache. '
             'These timings cover generation, excluding model startup, and use no synchronizing profiler. '
             'Speedup is the median of paired generation-time ratios, not the ratio of the two pooled medians.', '',
             '| Model | Generated tokens | Base ms/step | New ms/step | Paired speedup | Pair range |',
             '|---|---:|---:|---:|---:|---:|']
    for arch in ['llada', 'dream']:
        data = json.loads((DEST / (arch + '.json')).read_text())
        assert not data['partial']
        assert all(r['ok'] and r['forward_passes'] == data['steps'] for r in data['runs'])
        for row in data['summary']:
            a, b = row['median_ms_per_step']['base'], row['median_ms_per_step']['new']
            ratios = row['paired_speedups']
            lines.append(f"| {arch} | {row['gen_length']} | {a:.3f} | {b:.3f} | {row['median_paired_speedup']:.3f}x | {min(ratios):.3f}–{max(ratios):.3f}x |")
    lines += ['', 'The longest LLaDA case and its 256-token case are effectively unchanged. '
              'The benefit depends on shape; the Dream 128-token pair range also reflects prompt-length differences.', '',
              '## Preservation checks', '']
    for arch in ['llada', 'dream']:
        p = ROOT / f'bench/checks/2026-10-30-6000d-dispatch-{arch}-exact.json'
        exact = json.loads(p.read_text())
        assert all(r['bytes_equal'] for r in exact['logits'])
        assert all(r['tokens_equal'] for r in exact['generation'])
        count = sum(r['values'] for r in exact['logits'])
        lines.append(f"- {arch}: {len(exact['logits'])} logit canvases, {count:,} finite float values checked byte for byte; {len(exact['generation'])} complete generated token lists equal. Mask ID {exact['mask_id']}.")
    lines += ['', 'These checks compare the base GPU implementation with the new GPU implementation. '
              'They do not establish independent model parity or improved model accuracy.', '',
              '## Reproduce', '',
              'Build the base and candidate commits recorded in `llada.json`/`dream.json` with '
              '`MOJO_DLLM_GPU_ARCH=sm_120 scripts/build.sh`. Run the commands in '
              '`docs/development.md` under “Comparing GPU dispatch changes”, adding '
              '`--lengths 128,256,512,1024` for the full matrix.', '',
              'The `tiles-*.jsonl` files are the initial synthetic-shape exploration on GPU 5, '
              'with fixed-width launches from base 70a0880. Build '
              '`bench/bench_gpu_tiles.mojo` with `scripts/build.sh`, then run it with token '
              'counts 64, 148, 276 and 532. These batched microbenchmarks include enqueue and '
              'synchronization time; they are not a substitute for the paired generation runs. '
              'The dispatch wave count is a heuristic, not an occupancy-counter measurement.', '']
    (DEST / 'README.md').write_text('\n'.join(lines), encoding='utf-8')


if __name__ == '__main__':
    main()
